    local envn = menu_world({ "GUI_HUD_Main", "NotesBrowser", "VideoCameraUI", "InventoryMenu" })
    -- a menu that is open while the camera jumps (a cutscene) within 6 s is still a menu
    vis.InventoryMenu = true
